const CODES = [
  'en', 'hi', 'bn', 'mr', 'te', 'ta', 'gu', 'ur', 'kn', 'or', 'ml', 'pa', 'as',
  'mai', 'sat', 'ks', 'ne', 'kok', 'sd', 'doi', 'mni', 'brx', 'sa', 'bho', 'raj', 'tcy',
] as const

function row(values: string[]): Record<string, string> {
  if (values.length !== CODES.length) {
    throw new Error('Expected 26 translations, got ' + values.length + ' for ' + values[0])
  }
  return Object.fromEntries(CODES.map((code, index) => [code, values[index]]))
}

